// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        blockNum = bound(blockNum, 1, 2 ** 256 - 1);
        // restrict to blocks where number % 15 == 1 (the shifted payout slot)
        vm.assume(blockNum % 15 == 1);
        vm.assume(actor != address(c));

        vm.roll(blockNum);
        vm.warp(block.timestamp + 1);

        uint256 before = address(c).balance;
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // Rule: at block.number % 15 == 1 the contract must NOT pay out;
        // it still holds at least its pre-call balance (which is >= 10 ether).
        assertTrue(address(c).balance >= before && before >= 10 ether);
    }
}
